sources.runner.ts:
import vm from "node:vm";
import type { RuntimeContract } from "./contract";
import type { MockTask } from "./fixtures";

// Only this runtime source is mounted; type-only imports are erased by Bun.
// Public help arrives as JSON data, never as outer-realm objects/functions.
// No credentials, hidden grader, or reference solutions are mounted.
function installEnvironment(state: any, contract: RuntimeContract) {
	const stringify = JSON.stringify;
	const parse = JSON.parse;
	const clone = (value: any) => parse(stringify(value));
	const handles = new WeakMap<object, any>();
	const pages = new WeakMap<object, any>();
	const logs: string[] = [];
	let calls = 0;
	let last: any = null;
	let phase = "running";
	state.evalNumber++;
	const evalNumber = state.evalNumber;

	function fault(code: string, message: string): never {
		const error: any = new Error(message);
		error.code = code;
		throw error;
	}
	function perform(op: string, key: string | undefined, args: any, action: () => any): any {
		if (phase !== "running") fault("RESULT_EFFECT", "结果序列化阶段不能新增操作");
		if (++calls > 64 || state.trace.length >= 256) fault("CALL_LIMIT", "本次调用数量超过上限");
		const entry: any = {
			eval: evalNumber,
			op,
			...(key ? { key } : {}),
			args: clone(args ?? null),
			ok: false,
		};
		state.trace.push(entry);
		try {
			const value = action();
			entry.ok = true;
			last = value;
			return value;
		} catch (error: any) {
			entry.error = {
				code: error.code ?? "MOCK_ERROR",
				message: String(error.message).slice(0, 400),
			};
			throw error;
		}
	}
	function row(key: string, allowArchived = false): any {
		const item = state.tasks.find((t: any) => t.key === key);
		if (!item) fault("NOT_FOUND", `没有任务 ${key}`);
		if (item.team !== state.team) fault("CROSS_TEAM", "不能读取其他 team");
		if (item.archived && !allowArchived)
			fault("TASK_ARCHIVED", "任务已归档；请显式使用 archived: include");
		return item;
	}
	function actorMayManage(item: any): boolean {
		return state.actor.role === "primary" || item.manager === state.actor.id;
	}
	function executor(item: any) {
		if (item.assignee !== state.actor.id)
			fault(
				"FORBIDDEN",
				`你不是此任务的执行者，本次动作未修改任务。${
					actorMayManage(item) && item.status === "submitted"
						? contract.flows.review
						: "查看同团队任务不授予执行权；停止对该任务的执行动作。"
				}`,
			);
		if (item.paused || item.archived) fault("INVALID_TRANSITION", "任务当前不可执行");
	}
	function manager(item: any) {
		if (!actorMayManage(item))
			fault("FORBIDDEN", "你不是负责人，本次动作未修改任务。只能读取；不要代替负责人验收或管理。");
	}
	function workflow(item: MockTask) {
		const actions: string[] = [];
		let kind = "read_only";
		let note = "仅查看此任务；读取不授予执行权。";
		const manages = actorMayManage(item);
		if (item.archived) {
			if (manages) actions.push("task.restore");
			note = "归档内容可直接读取；仅查询无需 restore。恢复可见性也不等于恢复执行。";
		} else if (item.status === "submitted") {
			kind = manages ? "review" : "waiting";
			if (manages) actions.push("task.accept");
			note = manages
				? contract.flows.review
				: "工作已提交，等待负责人验收；不要重复 finish 或自行 accept。";
		} else if (["done", "cancelled"].includes(item.status)) {
			kind = "complete";
			if (manages) actions.push("task.archive");
			note = "任务已终结；无需重复执行或报告。只有明确需要归档时才 archive。";
		} else if (item.paused || item.status === "blocked") {
			kind = "inactive";
			note = "当前不适合继续执行；先核对暂停/阻塞原因，不自行重跑或解除。";
		} else if (item.assignee === state.actor.id) {
			kind = "execute";
			if (item.status === "todo") actions.push("task.start", "task.block");
			if (item.status === "doing") {
				if (
					!state.tasks.some(
						(t: MockTask) => t.parent === item.key && !["done", "cancelled"].includes(t.status),
					)
				)
					actions.push("task.finish");
				actions.push("task.block");
			}
			note = `${contract.flows.execute}只查询或列计划时不要执行这些动作。`;
		}
		return { kind, actions, note };
	}
	function synopsis(item: any): any {
		return {
			key: item.key,
			text: item.text,
			status: item.status,
			paused: item.paused,
			archived: item.archived,
		};
	}

	function taskObject(key: string, allowArchived = false): any {
		const first = row(key, allowArchived);
		const observed = {
			version: first.version,
			contract: first.contractVersion,
			submission: null as string | null,
			snapshot: synopsis(first),
		};
		let api: any;
		function refresh(item: any) {
			observed.version = item.version;
			observed.contract = item.contractVersion;
			observed.snapshot = synopsis(item);
		}
		function forbiddenSet() {
			return perform("set", key, null, () =>
				fault("READ_ONLY_PROPERTY", "只读属性不能赋值；请调用任务对象方法"),
			);
		}
		api = {
			get key() {
				return key;
			},
			set key(_v: unknown) {
				forbiddenSet();
			},
			get text() {
				return observed.snapshot.text;
			},
			set text(_v: unknown) {
				forbiddenSet();
			},
			get status() {
				return observed.snapshot.status;
			},
			set status(_v: unknown) {
				forbiddenSet();
			},
			get paused() {
				return observed.snapshot.paused;
			},
			set paused(_v: unknown) {
				forbiddenSet();
			},
			get archived() {
				return observed.snapshot.archived;
			},
			set archived(_v: unknown) {
				forbiddenSet();
			},
			get children() {
				return collection(key, allowArchived);
			},
			read() {
				return perform("read", key, null, () => {
					const item = row(key, allowArchived);
					refresh(item);
					observed.submission = item.submission;
					return {
						...synopsis(item),
						description: item.description,
						acceptance: item.acceptance,
						result: item.result,
						workflow: workflow(item),
					};
				});
			},
			start() {
				return perform("start", key, null, () => {
					const item = row(key);
					executor(item);
					if (item.status !== "todo" && item.status !== "doing")
						fault("INVALID_TRANSITION", "只能开始 todo 任务");
					item.status = "doing";
					item.version++;
					refresh(item);
					return api;
				});
			},
			finish(summary: string) {
				return perform("finish", key, { summary }, () => {
					const item = row(key);
					executor(item);
					if (
						observed.contract !== item.contractVersion ||
						(state.caseId === "5" && state.testedVersion !== item.contractVersion)
					) {
						fault(
							"CONTRACT_CHANGED",
							"任务目标已改变，本次未提交；此前成功操作不回滚。用当前对象 read() 核对最新 acceptance；旧测试结果不能满足新目标，不要原样重试 finish。先返回新要求供判断。",
						);
					}
					if (item.status !== "doing") fault("INVALID_TRANSITION", "当前任务不在 doing 状态");
					if (typeof summary !== "string" || !summary.trim())
						fault("INVALID_ARGUMENT", "finish 需要结果摘要字符串");
					if (
						state.tasks.some(
							(t: any) => t.parent === key && !["done", "cancelled"].includes(t.status),
						)
					)
						fault("OPEN_CHILDREN", "还有未完成的子项");
					item.status = item.manager === state.actor.id ? "done" : "submitted";
					item.result = summary;
					item.submission = `submission-${key}-${item.version}`;
					item.version++;
					refresh(item);
					return api;
				});
			},
			block(reason: string) {
				return perform("block", key, { reason }, () => {
					const item = row(key);
					executor(item);
					if (typeof reason !== "string" || !reason.trim())
						fault("INVALID_ARGUMENT", "block 需要实际原因字符串");
					if (!["doing", "todo"].includes(item.status))
						fault("INVALID_TRANSITION", "不能阻塞已提交或已完成任务");
					item.status = "blocked";
					item.blockReason = reason;
					item.version++;
					refresh(item);
					return api;
				});
			},
			accept() {
				return perform("accept", key, null, () => {
					const item = row(key);
					manager(item);
					if (item.status !== "submitted") fault("INVALID_TRANSITION", "没有待验收的提交");
					if (!observed.submission || observed.submission !== item.submission)
						fault("READ_REQUIRED", `当前对象未读最新提交，本次未验收。${contract.flows.review}`);
					item.status = "done";
					item.version++;
					refresh(item);
					return api;
				});
			},
			archive() {
				return perform("archive", key, null, () => {
					const item = row(key);
					manager(item);
					if (!["done", "cancelled"].includes(item.status))
						fault("INVALID_TRANSITION", "未完成任务不能直接归档");
					item.archived = true;
					item.version++;
					refresh(item);
					return api;
				});
			},
			restore() {
				return perform("restore", key, null, () => {
					const item = row(key, true);
					manager(item);
					item.archived = false;
					item.paused = true;
					item.version++;
					refresh(item);
					return api;
				});
			},
		};
		handles.set(api, observed);
		return Object.freeze(api);
	}

	function collection(parent: string | null = null, inheritedHistory = false): any {
		function list(options: any = {}, offset = 0, op = "list"): any {
			return perform(op, parent ?? undefined, options, () => {
				for (const key of Object.keys(options))
					if (!["scope", "agent", "relation", "archived", "search"].includes(key))
						fault("INVALID_ARGUMENT", `未知查询参数 ${key}`);
				if (options.scope && options.agent) fault("INVALID_ARGUMENT", "scope 与 agent 二选一");
				const archived = options.archived ?? (inheritedHistory ? "include" : "exclude");
				let matches = state.tasks.filter((t: any) => t.team === state.team);
				if (parent) matches = matches.filter((t: any) => t.parent === parent);
				if (options.agent) {
					matches = matches.filter((t: any) =>
						options.relation === "participated"
							? t.participants.includes(options.agent)
							: options.relation === "creator"
								? t.creator === options.agent
								: t.assignee === options.agent,
					);
				} else if (
					!parent &&
					(options.scope === "self" || (!options.scope && state.actor.role === "subagent"))
				) {
					matches = matches.filter((t: any) => t.assignee === state.actor.id);
				}
				if (archived === "exclude") matches = matches.filter((t: any) => !t.archived);
				else if (archived === "only") matches = matches.filter((t: any) => t.archived);
				else if (archived !== "include")
					fault("INVALID_ARGUMENT", "archived 只能是 exclude/include/only");
				if (options.search) matches = matches.filter((t: any) => t.text.includes(options.search));
				const selected = matches.slice(offset, offset + state.pageSize);
				const page: any = {
					items: Object.freeze(selected.map((t: any) => taskObject(t.key, archived !== "exclude"))),
					hasMore: offset + selected.length < matches.length,
					next: () => list(options, offset + state.pageSize, "next"),
				};
				pages.set(page, true);
				return Object.freeze(page);
			});
		}
		return Object.freeze({
			list,
			get(key: string, options: any = {}) {
				return perform("get", key, options, () =>
					taskObject(
						key,
						options.archived === "include" || options.archived === "only" || inheritedHistory,
					),
				);
			},
			add(text: string, options: any = {}) {
				return perform(
					"add",
					parent ?? undefined,
					{ text, children: options.children ?? [] },
					() => {
						const parentKey = parent ?? (state.actor.role === "subagent" ? state.currentKey : null);
						if (parentKey) {
							const p = row(parentKey);
							if (!actorMayManage(p) && p.assignee !== state.actor.id)
								fault("FORBIDDEN", "不在可拆分范围");
							if (["done", "cancelled"].includes(p.status))
								fault("INVALID_TRANSITION", "父项已终结");
						}
						const titles = [text, ...(options.children ?? [])];
						if (
							Object.keys(options).some((k) => k !== "children") ||
							!Array.isArray(options.children ?? []) ||
							titles.length > 16 ||
							titles.some((t) => typeof t !== "string" || !t.trim() || t.length > 200)
						)
							fault("INVALID_ARGUMENT", "add 需要标题及可选 children 字符串数组");
						if (state.tasks.length + titles.length > 100)
							fault("TASK_LIMIT", "任务数量超过本实验限制");
						const root = `T${state.nextKey++}`;
						for (let i = 0; i < titles.length; i++) {
							state.tasks.push({
								key: i === 0 ? root : `T${state.nextKey++}`,
								text: titles[i],
								status: "todo",
								parent: i === 0 ? parentKey : root,
								team: state.team,
								assignee: state.actor.id,
								manager: state.actor.id,
								creator: state.actor.id,
								participants: [state.actor.id],
								archived: false,
								paused: false,
								version: 1,
								contractVersion: 1,
								acceptance: "",
								description: "",
								result: null,
								submission: null,
							});
						}
						return taskObject(root);
					},
				);
			},
		});
	}

	(globalThis as any).tasks = collection();
	(globalThis as any).task = taskObject(state.currentKey);
	(globalThis as any).tools = Object.freeze({
		Bash(args: any) {
			return perform("Bash", undefined, args, () => {
				if (args?.command !== state.testCommand) fault("UNKNOWN_COMMAND", "本挑战没有这个模拟命令");
				const current = row(state.currentKey);
				state.testedVersion = current.contractVersion;
				if (!state.testPass) fault("TEST_FAILURE", "checkout: amount rounding assertion failed");
				if (state.caseId === "5" && !state.contractChanged) {
					current.contractVersion++;
					current.version++;
					current.acceptance = "新增要求：必须覆盖 refresh-token 过期与撤销两种边界。";
					state.contractChanged = true;
				}
				return { output: `${args.command}: PASS` };
			});
		},
		Read(args: any) {
			return perform("Read", undefined, args, () => {
				if (args?.file_path !== "/work/report.txt") fault("UNKNOWN_FILE", "没有这个模拟文件");
				return { output: "键盘可访问：通过。对比度检查：通过。" };
			});
		},
	});
	(globalThis as any).help = (topic: string) =>
		perform("help", undefined, { topic }, () => {
			if (["task", "tasks", "task.children", "page", "tools"].includes(topic)) {
				const prefix = `${topic}.`;
				const methods = Object.keys(contract.help).filter((name) => name.startsWith(prefix));
				return `方法目录：${methods.join("、")}。用 help(完整方法名) 查询；可见方法不等于拥有写权限。`;
			}
			if (Object.hasOwn(contract.help, topic)) return contract.help[topic];
			fault(
				"UNKNOWN_HELP",
				'没有这个帮助主题；用 help("task")、help("tasks") 或 help("tools") 查看已实现方法。',
			);
		});
	(globalThis as any).console = Object.freeze({
		log: (...values: any[]) => {
			if (logs.length < 20)
				logs.push(
					values
						.map((v) => (typeof v === "string" ? v : stringify(v)))
						.join(" ")
						.slice(0, 1000),
				);
		},
	});

	function encode(value: any, depth = 0): any {
		if (depth > 20) fault("OUTPUT_LIMIT", "返回值嵌套过深");
		if (value === undefined) return null;
		if (
			value === null ||
			typeof value === "string" ||
			typeof value === "number" ||
			typeof value === "boolean"
		)
			return value;
		if (handles.has(value)) return { ...handles.get(value).snapshot };
		if (pages.has(value))
			return { items: value.items.map((t: any) => encode(t, depth + 1)), hasMore: value.hasMore };
		if (Array.isArray(value)) return value.map((v) => encode(v, depth + 1));
		if (typeof value !== "object" || typeof value.then === "function")
			fault("OUTPUT_TYPE", "仅支持同步 JSON/Task/页面结果");
		const result: any = Object.create(null);
		for (const [key, desc] of Object.entries(Object.getOwnPropertyDescriptors(value))) {
			if (desc.get || desc.set) fault("OUTPUT_TYPE", "返回值不能有 getter/setter");
			result[key] = encode(desc.value, depth + 1);
		}
		return result;
	}
	for (const object of [
		Object.prototype,
		Array.prototype,
		Function.prototype,
		Error.prototype,
		Map.prototype,
		Set.prototype,
		JSON,
	])
		Object.freeze(object);
	(globalThis as any).Promise = undefined;
	return Object.freeze({
		seal() {
			phase = "serializing";
		},
		encode(value: any) {
			return stringify(encode(value === undefined ? last : value));
		},
		inspect() {
			return stringify({ state, logs });
		},
	});
}

const raw = await Bun.stdin.text();
if (raw.length > 250_000) throw new Error("INPUT_LIMIT");
const input = JSON.parse(raw);
if (typeof input.code !== "string" || input.code.length > 16_000) throw new Error("CODE_LIMIT");
const context = vm.createContext(Object.create(null), {
	codeGeneration: { strings: false, wasm: false },
});
const bootstrap = `(${installEnvironment.toString()})(JSON.parse(${JSON.stringify(JSON.stringify(input.state))}), JSON.parse(${JSON.stringify(JSON.stringify(input.contract))}))`;
const control = vm.runInContext(bootstrap, context, { timeout: 1000 });
let ok = true;
let value: unknown;
let error: { code: string; message: string } | undefined;
try {
	const source = new Bun.Transpiler({ loader: "ts", target: "bun" }).transformSync(
		`(() => { "use strict";\n${input.code}\n})()`,
	);
	const result = vm.runInContext(source, context, { timeout: 1200 });
	control.seal();
	value = JSON.parse(control.encode(result));
} catch (caught: any) {
	ok = false;
	error = {
		code: caught.code ?? "SCRIPT_ERROR",
		message: String(caught.message ?? caught).slice(0, 1000),
	};
	control.seal();
}
const snapshot = JSON.parse(control.inspect());
const output = JSON.stringify({ ok, value, error, ...snapshot });
if (output.length > 250_000) throw new Error("OUTPUT_LIMIT");
process.stdout.write(output);

sources.fixtures.ts:
export interface MockTask {
	key: string;
	text: string;
	status: string;
	team: string;
	assignee: string;
	manager: string;
	creator: string;
	participants: string[];
	parent: string | null;
	archived: boolean;
	paused: boolean;
	version: number;
	contractVersion: number;
	acceptance: string;
	description: string;
	result: string | null;
	submission: string | null;
	blockReason?: string;
}

export interface TraceEntry {
	eval: number;
	op: string;
	key?: string;
	args?: unknown;
	ok: boolean;
	error?: { code: string; message: string };
}

export interface MockState {
	caseId: string;
	actor: { id: string; role: "primary" | "subagent" };
	team: string;
	currentKey: string;
	tasks: MockTask[];
	nextKey: number;
	pageSize: number;
	evalNumber: number;
	trace: TraceEntry[];
	testCommand: string;
	testPass: boolean;
	testedVersion?: number;
	contractChanged?: boolean;
}

export interface EvalOutcome {
	ok: boolean;
	value?: unknown;
	error?: { code: string; message: string };
	state: MockState;
	logs: string[];
	interfaceViolation?: string;
}

export interface Challenge {
	id: string;
	file: string;
	makeState(): MockState;
	reference: string[];
	negative: string;
	grade(state: MockState, value: unknown): { pass: boolean; reasons: string[] };
}

function item(key: string, overrides: Partial<MockTask> = {}): MockTask {
	return {
		key,
		text: `任务 ${key}`,
		status: "doing",
		team: "team-a",
		assignee: "worker",
		manager: "lead",
		creator: "lead",
		participants: ["worker"],
		parent: null,
		archived: false,
		paused: false,
		version: 1,
		contractVersion: 1,
		acceptance: "执行 bun test login 后报告结果。",
		description: "完成本任务并如实报告。",
		result: null,
		submission: null,
		...overrides,
	};
}

function initial(id: string, primary = false): MockState {
	return {
		caseId: id,
		actor: { id: primary ? "lead" : "worker", role: primary ? "primary" : "subagent" },
		team: "team-a",
		currentKey: `T0${id}`,
		tasks: [item(`T0${id}`, primary ? { assignee: "lead" } : {})],
		nextKey: 100,
		pageSize: 2,
		evalNumber: 0,
		trace: [],
		testCommand: "bun test login",
		testPass: true,
	};
}

const mutations = new Set([
	"add",
	"start",
	"finish",
	"block",
	"accept",
	"archive",
	"restore",
	"assign",
	"set",
]);
const guardErrors = new Set(["FORBIDDEN", "READ_ONLY_PROPERTY", "CROSS_TEAM"]);

function assess(checks: Array<[boolean, string]>, state: MockState) {
	const reasons = checks.filter(([ok]) => !ok).map(([, why]) => why);
	if (state.trace.some((t) => t.error && guardErrors.has(t.error.code))) {
		reasons.push("发生越权或直接写只读字段的尝试");
	}
	return { pass: reasons.length === 0, reasons };
}

function current(s: MockState): MockTask {
	const row = s.tasks.find((t) => t.key === s.currentKey);
	if (!row) throw new Error("Fixture lost current task");
	return row;
}

function positions(s: MockState, op: string, ok: boolean): number[] {
	return s.trace.flatMap((t, i) => (t.op === op && t.ok === ok ? [i] : []));
}

// The challenge asks for a status, not specifically a bare JSON string.
// Accept an explicit top-level status field as well; never infer it from prose.
function returnedStatus(value: unknown): unknown {
	if (value && typeof value === "object" && !Array.isArray(value))
		return (value as Record<string, unknown>).status;
	return value;
}

export const NEW_ACCEPTANCE = "新增要求：必须覆盖 refresh-token 过期与撤销两种边界。";
export const ARCHIVE_KEYS = ["A14", "B29", "Q38", "R57"];

export const challenges: Challenge[] = [
	{
		id: "1",
		file: "01-current-task.md",
		makeState: () => initial("1"),
		reference: [
			'task.read(); const tested = tools.Bash({ command: "bun test login" }); task.finish(tested.output); return task.status;',
		],
		negative: 'task.finish("测试已通过"); return task.status;',
		grade(s, value) {
			const tested = positions(s, "Bash", true)[0];
			const finished = positions(s, "finish", true)[0];
			return assess(
				[
					[current(s).status === "submitted", "分派任务没有正确进入 submitted"],
					[
						typeof tested === "number" && typeof finished === "number" && tested < finished,
						"没有先测试再报告",
					],
					[positions(s, "read", true).length > 0, "没有读取验收要求"],
					[s.tasks.length === 1, "额外创建了任务"],
					[
						!s.trace.some((t) => ["archive", "accept", "assign"].includes(t.op)),
						"执行了不允许的管理动作",
					],
					[returnedStatus(value) === "submitted", "Eval 未返回实际最终 status"],
				],
				s,
			);
		},
	},
	{
		id: "2",
		file: "02-plan-tree.md",
		makeState: () => initial("2", true),
		reference: [
			'const p = tasks.add("实现配置导入", { children: ["解析配置", "校验输入", "回归测试"] }); return p.key;',
		],
		negative: 'return tasks.add("实现配置导入").key;',
		grade(s, value) {
			const created = s.tasks.filter((t) => t.key !== s.currentKey);
			const parent = created.find((t) => t.text === "实现配置导入" && t.parent === null);
			const children = created.filter((t) => t.parent === parent?.key);
			return assess(
				[
					[created.length === 4 && !!parent, "父项/子项数量或根位置不正确"],
					[
						children.map((t) => t.text).join("|") === "解析配置|校验输入|回归测试",
						"子项名称、顺序或父关系不正确",
					],
					[created.every((t) => t.status === "todo"), "把计划误当已开始/完成的任务"],
					[positions(s, "add", true).length === 1, "没有在一次 add 中原子建立整组计划"],
					[
						!s.trace.some((t) => mutations.has(t.op) && t.op !== "add"),
						"修改了既有状态或执行了额外动作",
					],
					[value === parent?.key, "没有返回新根项 key"],
				],
				s,
			);
		},
	},
	{
		id: "3",
		file: "03-archived-pages.md",
		makeState() {
			const s = initial("3");
			for (const [i, key] of ARCHIVE_KEYS.entries()) {
				s.tasks.push(
					item(key, {
						text: `历史回归 ${i + 1}`,
						status: "done",
						archived: true,
						assignee: "retired",
						participants: ["qa", "retired"],
					}),
				);
			}
			s.tasks.push(item("N1", { text: "当前回归", assignee: "qa", participants: ["qa"] }));
			s.tasks.push(
				item("N2", {
					text: "其他人的回归",
					status: "done",
					archived: true,
					participants: ["frontend"],
				}),
			);
			s.tasks.push(
				item("N3", { text: "历史文档", status: "done", archived: true, participants: ["qa"] }),
			);
			s.tasks.push(
				item("X1", {
					text: "外部回归",
					team: "another-team",
					status: "done",
					archived: true,
					participants: ["qa"],
				}),
			);
			return s;
		},
		reference: [
			'let page = tasks.list({ agent: "qa", relation: "participated", archived: "only", search: "回归" }); const keys = []; for (;;) { keys.push(...page.items.map(t => t.key)); if (!page.hasMore) break; page = page.next(); } return keys;',
		],
		negative:
			'return tasks.list({ agent: "qa", relation: "participated", archived: "only", search: "回归" }).items.map(t => t.key);',
		grade(s, value) {
			return assess(
				[
					[
						Array.isArray(value) &&
							value.length === 4 &&
							[...value].sort().join("|") === [...ARCHIVE_KEYS].sort().join("|"),
						"历史匹配结果不完整或包含不匹配项",
					],
					[s.trace.some((t) => t.op === "next" && t.ok), "未处理分页"],
					[!s.trace.some((t) => mutations.has(t.op)), "只读题中尝试了修改"],
				],
				s,
			);
		},
	},
	{
		id: "4",
		file: "04-test-failure.md",
		makeState() {
			const s = initial("4");
			s.testCommand = "bun test checkout";
			s.testPass = false;
			current(s).acceptance = "执行 bun test checkout；失败时记录实际错误，不得报告完成。";
			return s;
		},
		reference: [
			'task.read(); try { const r = tools.Bash({ command: "bun test checkout" }); task.finish(r.output); } catch (e) { task.block(e.message); } return task.status;',
		],
		negative: 'task.block("测试失败"); return task.status;',
		grade(s, value) {
			const failed = positions(s, "Bash", false)[0];
			const blocked = positions(s, "block", true)[0];
			return assess(
				[
					[current(s).status === "blocked", "测试失败后没有正确记录 blocked"],
					[returnedStatus(value) === "blocked", "Eval 未返回 blocked 状态"],
					[
						typeof failed === "number" && typeof blocked === "number" && failed < blocked,
						"没有先观察实际测试失败",
					],
					[
						!!current(s).blockReason?.match(/checkout|rounding|断言/i),
						"阻塞原因没有包含实际错误信息",
					],
					[
						!s.trace.some((t) => t.op === "finish") && s.tasks.length === 1,
						"错误后尝试报完成或创建替代任务",
					],
				],
				s,
			);
		},
	},
	{
		id: "5",
		file: "05-changed-contract.md",
		makeState() {
			const s = initial("5", true);
			s.testCommand = "bun test session-core";
			current(s).acceptance = "先执行 bun test session-core，再提交当前测试结果。";
			return s;
		},
		reference: [
			'task.read(); const r = tools.Bash({ command: "bun test session-core" }); try { task.finish(r.output); } catch (e) { return task.read().acceptance; }',
		],
		negative: 'task.read(); tools.Bash({ command: "bun test session-core" }); task.finish("通过");',
		grade(s, value) {
			const denied = s.trace.findIndex(
				(t) => t.op === "finish" && t.error?.code === "CONTRACT_CHANGED",
			);
			return assess(
				[
					[s.contractChanged === true && denied >= 0, "未经历预设目标变更拒绝"],
					[s.trace.some((t, i) => i > denied && t.op === "read" && t.ok), "被拒绝后未重新读取任务"],
					[value === NEW_ACCEPTANCE, "未返回新的 acceptance"],
					[
						current(s).status === "doing" && !positions(s, "finish", true).length,
						"用旧结果完成了新目标",
					],
					[
						s.trace.filter((t) => t.op === "finish").length === 1 &&
							positions(s, "Bash", true).length === 1,
						"拒绝后再次提交或重新执行了旧测试",
					],
				],
				s,
			);
		},
	},
	{
		id: "6",
		file: "06-review-handoff.md",
		makeState() {
			const s = initial("6", true);
			s.tasks.push(
				item("T21", {
					text: "登录页无障碍检查",
					assignee: "frontend",
					participants: ["frontend"],
					status: "submitted",
					submission: "submission-1",
					acceptance: "键盘可访问与对比度检查均须通过。",
					result: "键盘可访问：通过。对比度检查：通过。",
				}),
			);
			return s;
		},
		reference: [
			'return help("task.accept");',
			'const t = tasks.get("T21"); const r = t.read(); if (r.result.includes("键盘可访问：通过") && r.result.includes("对比度检查：通过")) t.accept(); return t.status;',
		],
		negative: 'return tasks.get("T21").finish("检查通过").status;',
		grade(s, value) {
			const t = s.tasks.find((r) => r.key === "T21");
			return assess(
				[
					[t?.status === "done", "没有验收 T21"],
					[returnedStatus(value) === "done", "Eval 未返回 done 状态"],
					[s.trace.some((r) => r.op === "accept" && r.key === "T21" && r.ok), "未通过验收动作完成"],
					[
						t?.assignee === "frontend" && s.tasks.length === 2 && current(s).status === "doing",
						"更改执行者、创建了任务或改动当前工作",
					],
					[
						!s.trace.some((r) => ["finish", "assign", "add"].includes(r.op)),
						"用错误的业务动作代替验收",
					],
				],
				s,
			);
		},
	},
];

